glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
uniform highp vec4 cc_worldBoundCenter;
  uniform highp vec4 cc_worldBoundHalfExtents;
attribute vec3 a_position;
vec4 vert () {
  vec4 position;
  position = vec4(a_position, 1.0);
  position *= cc_worldBoundHalfExtents;
  position += cc_worldBoundCenter;
  position = cc_matViewProj * position;
  return position;
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision mediump float;
vec4 frag () {
  return vec4(1, 0, 0, 1);
}
void main() { gl_FragColor = frag(); }
